import { buildSchema, findBreakingChanges } from "graphql";

const current = buildSchema(`type Query { user: User } type User { id: ID! }`);
const proposed = buildSchema(`type Query { user: User } type User { id: ID! name: String }`);

const changes = findBreakingChanges(current, proposed);
if (changes.length) {
  for (const change of changes) console.error(change.type, change.description);
  process.exit(1);
}
console.log("No breaking changes detected");

